 geometric:{documentId:'textbook-c2',pdfPage:9,printedPage:2,section:'6.1'},
 coordinates:{documentId:'textbook-c2',pdfPage:32,printedPage:25,section:'6.3'},
 dot:{documentId:'textbook-c2',pdfPage:14,printedPage:7,section:'6.2'},
 triangles:{documentId:'textbook-c2',pdfPage:45,printedPage:38,section:'6.4'},
 ellipse:{documentId:'textbook-s1',pdfPage:110,printedPage:105,section:'3.1'},
