// Each row is separately authored: task type, prompt, givens, answer, two hints,
// connected derivation steps, result, and a specific correction.
const R=(kind,level,taskType,prompt,expression,answer,hints,steps,result,error,extra={})=>{
 const p=B(prompt),r=B(result);
 return Q(kind,level,p.en,p.zh,T(expression),typeof answer==='number'||kind==='choice'?answer:r,hints.map(B),
  steps.map(([body,math])=>{const b=B(body);return S(b.en,b.zh,T(math));}),r,B(error),{taskType,difficultyReview:'reviewed',...extra});
};
const E=(...a)=>R('example',...a),N=(...a)=>R('number',...a),W=(...a)=>R('written',...a);
const D=(task,prompt,expr,options,key,errors,hints,steps,result,error)=>R('choice','foundation',task,prompt,expr,key,hints,steps,result,error,{
 choices:options.map((expression,i)=>({id:'ABCD'[i],label:L('Option '+'ABCD'[i],'選項 '+'ABCD'[i]),expression:T(expression)})),
 distractorMisconceptions:Object.fromEntries(errors.map(([id,text])=>[id,B(text)])),
});
const concept=(role,title,body,formula)=>({role,title:B(title),body:B(body),...(formula?{formula:T(formula)}:{})});
